"use strict";(globalThis.webpackChunkuniwahl_doku||=[]).push([[3558],{2988(e,n,i){i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>a,default:()=>o,frontMatter:()=>l,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"releases/6.4","title":"Version 6.4","description":"\ud83d\ude80 Dieses Release konzentriert sich vorrangig auf die Verbesserung der Stabilit\xe4t und Leistungsf\xe4higkeit der Anwendung.","source":"@site/docs/releases/6.4.md","sourceDirName":"releases","slug":"/releases/6.4","permalink":"/uniwahl-doku/releases/6.4","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Version 6.4"},"sidebar":"doku","previous":{"title":"Version 6.5","permalink":"/uniwahl-doku/releases/6.5"},"next":{"title":"Version 6.3","permalink":"/uniwahl-doku/releases/6.3"}}');var t=i(4848),s=i(8453);const l={title:"Version 6.4"},a=void 0,d={},u=[];function h(e){const n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\ud83d\ude80 Dieses Release konzentriert sich vorrangig auf die Verbesserung der Stabilit\xe4t und Leistungsf\xe4higkeit der Anwendung."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Anzeige von Datumsangaben im Terminplan:"})," Eine Herausforderung in der Planung von Wahlen ist die Koordination und das Timing der verschiedenen Phasen und Fristen, die strikt eingehalten bzw. an die Wahlordnung angepasst werden m\xfcssen. Wenn Sie Ihren Terminplan in uniWAHL erstellen, werden Ihnen neben der traditionellen Anzeige der verbleibenden Tage bis zu einem bestimmten Wahlereignis nun auch die spezifischen Datumsangaben f\xfcr jedes Ereignis angezeigt. Dies hilft Ihnen, auf einen Blick zu erkennen, an welchem Tag und Datum jedes wichtige Ereignis stattfindet. Die Terminplanfunktionalit\xe4t l\xe4sst sich dadurch nun noch besser benutzen. Die Texte der einzelnen Termine sind in den Textbausteinen individuell anpassbar und es kann ein Termin-Template im Arbeitsverzeichnis bearbeitet und genutzt werden, so dass Sie zuk\xfcnftig nur noch den 1. Wahltag in uniWAHL neu festlegen m\xfcssen, um mit dem Men\xfc \u201eAusgabe\u201c \u2013 \u201eTerminplan\u201c direkt in einen neuen Wahlzyklus starten zu k\xf6nnen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Zahl der ung\xfcltigen Stimmen:"})," Eine Erg\xe4nzung zur Software uniWAHL ist die Erfassung und Ausgabe der Anzahl ung\xfcltiger Stimmen im Wahlergebnis. Diese Funktion bietet eine Erweiterung f\xfcr mehr Transparenz und Genauigkeit des Wahlprozesses und ist Anforderung bzw. Bestandteil zahlreicher Wahlordnungen. Ein Vorteil dieser Funktion liegt in der M\xf6glichkeit, die Qualit\xe4t des Wahlprozesses kontinuierlich zu verbessern. Durch die Analyse der ung\xfcltigen Stimmen k\xf6nnen h\xe4ufige Fehlerquellen identifiziert und zuk\xfcnftig vermieden werden. Beispielsweise k\xf6nnte eine hohe Zahl an ung\xfcltigen Stimmen auf Probleme beim Verst\xe4ndnis des Wahlverfahrens oder technische Schwierigkeiten hinweisen. Mit dieser Erkenntnis k\xf6nnen gezieltere Anpassungen an den Wahlunterlagen vorgenommen werden, um die Verst\xe4ndlichkeit und Nutzerfreundlichkeit zu erh\xf6hen. In der \u201eKonfiguration\u201c \u2013 \u201eWahlordnung\u201c kann nun die Anzeige \u201eSollen ung\xfcltige Stimmen gez\xe4hlt werden?\u201c aktiviert werden. Es werden fortan alle Stimmen als ung\xfcltig erfasst, die explizit als \u201eung\xfcltig w\xe4hlen\u201c (nur online) oder implizit ung\xfcltig (z.B. zu viele Stimmen) abgegeben wurden. Dies weicht von der bisherigen reinen Darstellung \u201eung\xfcltiger Stimmzettel\u201c in uniWAHL ab. Beim Import von Stimmzettelrohdaten aus uniSCAN oder uniWAHL OWS werden diese Angaben bereits im Ausz\xe4hlungsprotokoll als Zahlenwerte g\xfcltiger Stimmzettel und ung\xfcltiger Stimmen ausgegeben, wenn die Option in der Wahlordnung aktiviert ist. In den Textbausteinen im Register \u201eWahlergebnis\u201c k\xf6nnen nun die Textbausteine \u201eG\xfcltige Stimmzettel\u201c und \u201eUng\xfcltige Stimmen\u201c angepasst werden. Wenn aktiviert, erscheint im Fenster \u201eZ\xe4hlen und Auswerten\u201c jeder Gruppe bzw. jedes Wahlbereichs oben im Bereich \u201eStimmen\u201c ein neues Eingabefeld \u201eung\xfcltige Stimmen\u201c, in dem diese Stimmen manuell eingegeben oder gepr\xfcft werden k\xf6nnen. Der Inhalt des Feldes wird als Anzahl ung\xfcltiger Stimmen im Statistikblock des Wahlergebnisses ausgegeben."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"W\xe4hlergruppen-Verwaltung:"})," Nutzer",":innen"," profitieren nun von einer noch schnelleren und einfacheren Verwaltung der W\xe4hlergruppen, was insbesondere bei komplex strukturierten Wahlen von gro\xdfem Vorteil ist. Der Dialog \u201eWahlverzeichnis kodieren\u201c wurde vereinfacht. In der Vergangenheit konnte das Erstellen von W\xe4hlergruppen durch unterschiedliche Trennzeichen in Datens\xe4tzen zu Fehlern f\xfchren. Mit der neuen Einstellung, dass nun das Komma als vorbesetztes Trennzeichen verwendet wird, ist dieser Prozess deutlich fehlerresistenter. Anstatt jede Kombination manuell zu pr\xfcfen, bietet das Excel-Tabellenblatt 2 in \u201eW\xe4hlergruppen kontrollieren\u201c nun eine vollst\xe4ndige \xdcbersicht aller W\xe4hlergruppen-Kombinationen, die es den Nutzer",":innen"," erleichtert, Fehler leichter zu erkennen. Dies ist besonders n\xfctzlich in komplexen Wahlprojekten, wo viele verschiedene Gruppen involviert sind. Die F\xe4higkeit, W\xe4hlergruppen direkt aus uniWAHL mit den Inhalten des W\xe4hlerverzeichnisses abzugleichen, wenn JSON-Konfigurationsdateien erzeugt werden, ist ein weiterer bedeutender Vorteil. Dies stellt sicher, dass alle Daten konsistent sind. Die Automatisierung dieses Prozesses reduziert nicht nur den manuellen Aufwand erheblich, sondern minimiert auch das Risiko von Inkonsistenzen zwischen dem Wahlverzeichnis und der W\xe4hlergruppenkonfiguration."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Vereinfachung des Login in uniWAHL OWS:"})," Traditionell k\xf6nnen mehrere Authentifizierungsmethoden wie PIN/TAN, SmartLink oder OpenID in uniWAHL OWS genutzt bzw. angezeigt werden. Das Online-Wahlsystem stellt dabei sicher, dass egal welche Anmeldemethode gew\xe4hlt wird, die Stimmabgabe pro W\xe4hler",":in"," nur einmal erfolgen kann. Diese Authentifizierung wurden bisher in unterschiedlichen Registerkarten auf der Login-Seite dargestellt. Das konnte insbesondere f\xfcr weniger technikaffine Nutzer",":innen"," verwirrend sein, da man zur Eingabe seiner Login-Daten noch eine Registerkarte ausw\xe4hlen musste. Mit der neuen Funktion, dass bei Nutzung nur eines Authentifizierungsverfahrens nun keine Registerkarten mehr angezeigt werden, wird die Login-Maske deutlich \xfcbersichtlicher und benutzerfreundlicher. Nutzer",":innen"," werden direkt zur Eingabe ihrer Anmeldedaten geleitet, ohne durch zus\xe4tzliche Optionen navigieren zu m\xfcssen. Werden mehrere Authentifizierungsverfahren (z.B. SmartLink und PIN/TAN) in Kombination genutzt, werden die Verfahren von der Login-Maske bevorzugt angezeigt, in denen eine Eingabe von Login-Daten notwendig ist. Es kann nun beim Upload von W\xe4hlerverzeichnissen in uniWAHL OWS auch ein eigenes Merkmal als PIN angegeben werden. So l\xe4sst sich der Login in uniWAHL OWS noch einfacher und sicherer gestalten, da z.B. einfach die eigene Personennummer, Mitgliedsnummer oder vordefinierte W\xe4hler-ID zum Login im PIN/TAN-Verfahren genutzt werden kann."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Digitale \xdcberpr\xfcfung der Wahlberechtigung integriert:"})," Die Integration der digitalen \xdcberpr\xfcfung der Wahlberechtigung direkt in das uniWAHL Produkt stellt eine wesentliche Verbesserung dar, die den Prozess der Wahlorganisation weiter vereinfacht und optimiert. Es kann nun eine JSON-Konfiguration-Datei erstellt werden, die es Wahlleiter",":innen"," erm\xf6glicht, das Wahlverzeichnis direkt online auszulegen. Diese Funktion bietet somit eine nahtlose M\xf6glichkeit, die Wahlberechtigung durch W\xe4hler",":innen"," \xfcberpr\xfcfen zu lassen, was vor allem f\xfcr komplex strukturierte Wahlprojekte von gro\xdfem Vorteil ist. Sobald die W\xe4hler",":innen"," ihre Zugangsdaten eingeben, pr\xfcft das System automatisch die Berechtigung anhand der hinterlegten W\xe4hlergruppen. Dieser Prozess erfolgt vollst\xe4ndig integriert und ohne die Notwendigkeit, auf externe Systeme oder manuelle \xdcberpr\xfcfungsverfahren zur\xfcckgreifen zu m\xfcssen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Impressum / Datenschutzangaben:"})," Die M\xf6glichkeit der Anzeige von Impressum und Datenschutzlink in der Online-Wahlkabine, ist eine wichtige Erg\xe4nzung, die der Transparenz des Wahlsystems Rechnung tr\xe4gt. Durch die Einbindung der Links im Fu\xdfbereich der Wahlkabine k\xf6nnen die Nutzer",":innen"," w\xe4hrend des Wahlvorgangs direkt auf rechtliche Informationen zugreifen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Wahlbeteiligungs\xfcbersicht in uniWAHL OWS:"})," Die neue Funktion der grafischen Darstellung der Wahlbeteiligung sowie die M\xf6glichkeit zum Download der Beteiligungsdaten im uniWAHL Online-Wahlsystem (OWS), bietet eine innovative und praktische L\xf6sung f\xfcr die \xdcberwachung und Analyse laufender Wahlprozesse. Diese Funktion erleichtert es den Wahlverantwortlichen, die Teilnahme in Echtzeit zu verfolgen, aber auch historische Daten effizient zu analysieren. Die Grafik zeigt die Beteiligten in verschiedenen zeitlichen Darstellungen der Wahl oder in verschiedenen Wahlbereichen an. Zus\xe4tzlich zur grafischen Ansicht k\xf6nnen Nutzer",":innen"," die Daten zur Wahlbeteiligung herunterladen, um detailliertere Analysen durchzuf\xfchren oder Berichte f\xfcr Stakeholder zu erstellen."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\u2699\ufe0fWeitere \xc4nderungen und Fehlerbehebungen"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs wurde ein Problem im Gruppenlayout behoben, so dass bei Klick auf \u201eStandard\u201c nun wieder korrekt das allgemeine Layout angezeigt wird."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eDie Funktion \u201eSchriftboxh\xf6he Nachnom.\u201c f\xfcr Papierstimmzettel in Wahlen ohne Bindung an Wahlvorschl\xe4ge war ohne Funktion. Das wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eDie Option \u201eRangreihenfolge\u201c beim Erzeugen von Wahlergebnissen funktionierte nicht korrekt, dieses Problem wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eIm Layout des \u201eWahlergebnis\u201c wurden Ver\xe4nderungen in den \u201eKandidatenfeldern\u201c nicht gespeichert, das wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eWenn Personenbezeichner umbenannt oder \xfcbersetzt wurden, wurde dies nicht korrekt im Gruppenlayout aktualisiert. Dieses Problem wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eBeim Import von Rohdaten wurde die XLSX-Datei der (Nach-)Nominierten fehlerhaft dargestellt. Die Datei wird nun korrekt erzeugt."}),"\n",(0,t.jsx)(n.li,{children:'\u2705Der Text "Standard-Anzahl der Gruppen/Wahlkreise pro Gremium" im Wahlprojekt wurde ge\xe4ndert, so dass deutlicher wird, welche Zahl hier angegeben wird.'}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eBeim wiederholten Import von gleichnamigen Wahlverzeichnissen kam es aufgrund eines Caching-Problems zu fehlerhaften Darstellungen. Der Import wurde \xfcberarbeitet."}),"\n",(0,t.jsxs)(n.li,{children:["\ud83d\udc1eDie Funktion \u201ePers\xf6nliche Vertretung\u201c wurde im Stimmzettel nicht korrekt dargestellt. Vertreter",":innen"," oder Ersatzkandidat",":innen"," k\xf6nnen nun wieder dargestellt werden."]}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eBei komplexeren Importdateien konnte es zu Fehlern in der Funktion \u201eImportiere Wahl\u201c kommen. Wir haben mehrere Probleme behoben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eWurde im allgemeinen Layout benutzerdefiniertes CSS zur Online-Wahlkabine \xfcbertragen, wurde das nicht ins Gruppenlayout \xfcbernommen. Das wurde behoben."}),"\n",(0,t.jsxs)(n.li,{children:["\ud83d\udc1eEs wurde ein Problem in uniSCAN beim Importieren von Stimmen behoben, das auftrat, wenn Stimmzettel neben Kandidat",":innen"," noch \xfcber freie Eingabefelder verf\xfcgten."]}),"\n",(0,t.jsxs)(n.li,{children:["\ud83d\udc1eEs wurde ein Problem in uniWAHL OWS behoben, das auftrat, wenn Stimmzettel neben Kandidat",":innen"," noch \xfcber freie Eingabefelder verf\xfcgten."]}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Live-Preview von Wahlkabinen in uniWAHL OWS wurde weiter verbessert, so wurde die Stabilit\xe4t verbessert und es wurden verschiedene CSS Optimierungen vorgenommen."}),"\n"]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}},8453(e,n,i){i.d(n,{R:()=>l,x:()=>a});var r=i(6540);const t={},s=r.createContext(t);function l(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:l(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);